def build_controller():
    return {
        "name": "det_tsp_hh_oracle_portfolio_v2",
        "description": "Deterministic instance-adaptive scheduler over a frozen TSP heuristic portfolio with interpretable structure tests and stagnation-triggered switching.",
        "default_heuristic": "farthest_insertion_two_opt",
        "random_like_heuristic": "nearest_neighbor_multistart",
        "clustered_heuristic": "cluster_first_local_search",
        "grid_like_heuristic": "candidate_pruned_two_opt",
        "two_cluster_bottleneck_heuristic": "edge_preserving_restart",
        "corridor_heuristic": "limited_three_opt",
        "nearest_neighbor_trap_heuristic": "annealed_multi_start",
        "stagnation_switch_heuristic": "nearest_neighbor_multistart",
        "stagnation_threshold": 4,
        "low_improvement_threshold": 0.1,
        "failed_perturbation_threshold": 3,
        "time_budget_trigger": 0.65,
        "candidate_limit_offset": 1,
        "restart_offset": 2,
        "temperature_scale": 1.2,
        "acceptance_bias": 0.007,
        "policy": {
            "deterministic_selection_order": [
                "nearest_neighbor_trap",
                "two_cluster_bottleneck",
                "corridor",
                "grid_like",
                "clustered",
                "default"
            ],
            "tests": {
                "nearest_neighbor_trap": {
                    "use_if": "nearest-neighbor-trap-score >= 0.26 OR nn_distance_cv >= 0.62",
                    "heuristic": "nearest_neighbor_trap_heuristic"
                },
                "two_cluster_bottleneck": {
                    "use_if": "bottleneck-score >= 0.52 OR structure_class == 'two_cluster_bottleneck'",
                    "heuristic": "two_cluster_bottleneck_heuristic"
                },
                "corridor": {
                    "use_if": "corridor_score >= 0.44 AND grid_likeness <= 0.20",
                    "heuristic": "corridor_heuristic"
                },
                "grid_like": {
                    "use_if": "grid_likeness >= 0.28 OR convex_hull_ratio <= 0.78",
                    "heuristic": "grid_like_heuristic"
                },
                "clustered": {
                    "use_if": "clustering-score >= 0.42 OR structure_class == 'clustered'",
                    "heuristic": "clustered_heuristic"
                }
            },
            "online_schedule_rules": {
                "stagnation_switch": {
                    "trigger_if": "stagnation_length >= stagnation_threshold OR (recent_improvement_rate < low_improvement_threshold AND accepted_swaps == 0)",
                    "switch_to": "stagnation_switch_heuristic",
                    "offsets": {
                        "candidate_limit_offset": "candidate_limit_offset if grid_likeness >= 0.25 else 0",
                        "restart_offset": "restart_offset if time_budget_used >= 0.35 else 1"
                    }
                },
                "perturbation_escalation": {
                    "trigger_if": "failed_perturbation_count >= failed_perturbation_threshold AND time_budget_used >= time_budget_trigger",
                    "escalate_to": {
                        "if_current_heuristic_contains": "annealed_multi_start",
                        "then": "annealed_multi_start",
                        "else": "edge_preserving_restart"
                    },
                    "temperature_tuning": {
                        "temperature_scale": "temperature_scale",
                        "acceptance_bias": "acceptance_bias"
                    }
                },
                "late_stage_refinement_preference": {
                    "trigger_if": "time_budget_used >= (time_budget_trigger + 0.18)",
                    "policy": "favor backbone-style 2-opt refinement; if current heuristic is grid_like/candidate_pruned, stay with it; otherwise only switch on stagnation_switch trigger (no additional portfolio cycling)."
                }
            },
            "restart_budgeting": {
                "max_restarts": "1 + (restart_offset if stagnation_length >= 2 else 0)",
                "candidate_list_bias": "candidate_limit_offset if grid_likeness >= 0.25 else 0"
            }
        },
        "margins": {
            "min_structure_certainty_for_specialization": 0.08,
            "prefer_default_when_multiple_tests_fire": True
        }
    }

